def is_forbidden(log_msg, forbidden):
    return forbidden.lower() in log_msg.lower()

# Example:
print(is_forbidden('Error: disk failure', 'DISK'))  # True
print(is_forbidden('All systems OK', 'DISK'))       # False

def validate_product_code(code):
    required = {'a', 'b', 'c'}
    code_lower = code.lower()
    return all(ch in code_lower for ch in required)

# Examples:
print(validate_product_code('aBc123'))   # True
print(validate_product_code('abc'))        # True
print(validate_product_code('ab'))         # False
